<?phpnamespace app\store\controller\statistics;use app\store\controller\Controller;use app\store\model\RechargeLog as RechargeLogModel;use think\facade\View;/** * 用户充值控制器 */class Recharge extends Controller{    /**     * 充值记录列表     */    public function logs()    {        $model = new RechargeLogModel;        $list = $model->getList();        return View::fetch('logs', compact('list'));    }}